using Kindred.Domain.Common;
using Microsoft.EntityFrameworkCore;

namespace Kindred.Infrastructure.Persistence;

/// <summary>
/// Persistence conventions applied to every entity (Section 4, foundation and conventions):
/// <list type="bullet">
/// <item>UUIDv7 keys generated by the application, never by the database.</item>
/// <item>PostgreSQL <c>xmin</c> as the optimistic concurrency token on every mutable table. Entities
/// marked <see cref="IAppendOnly"/> are the documented exception.</item>
/// <item>No cascading deletes: every relationship is ON DELETE RESTRICT.</item>
/// <item>Instants are <see cref="DateTimeOffset"/> stored as <c>timestamptz</c> in UTC; plain
/// <see cref="DateTime"/> properties are rejected.</item>
/// </list>
/// Snake_case naming comes from <c>UseSnakeCaseNamingConvention</c> in the context options.
/// </summary>
public static class ModelConventions
{
    public const string ConcurrencyTokenProperty = "xmin";

    public static void Apply(ModelBuilder modelBuilder)
    {
        foreach (var entityType in modelBuilder.Model.GetEntityTypes().Where(t => !t.IsOwned()).ToList())
        {
            var clrType = entityType.ClrType;
            var builder = modelBuilder.Entity(clrType);

            if (typeof(Entity).IsAssignableFrom(clrType) && entityType.BaseType is null)
            {
                builder.HasKey(nameof(Entity.Id));
                builder.Property(nameof(Entity.Id)).ValueGeneratedNever();
            }

            if (!typeof(IAppendOnly).IsAssignableFrom(clrType) && entityType.BaseType is null)
            {
                builder.Property<uint>(ConcurrencyTokenProperty)
                    .HasColumnName(ConcurrencyTokenProperty)
                    .HasColumnType("xid")
                    .ValueGeneratedOnAddOrUpdate()
                    .IsConcurrencyToken();
            }

            foreach (var property in entityType.GetProperties())
            {
                if (property.ClrType == typeof(DateTime) || property.ClrType == typeof(DateTime?))
                {
                    throw new InvalidOperationException(
                        $"{clrType.Name}.{property.Name} is a DateTime. Use DateTimeOffset so instants are stored as UTC timestamptz.");
                }
            }

            foreach (var foreignKey in entityType.GetForeignKeys())
            {
                foreignKey.DeleteBehavior = DeleteBehavior.Restrict;
            }
        }
    }
}
